def transform(grid):
    """Extend a two-cell marker toward the full-width colored bar with an 8 stripe."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = 4
    bar_rows = [r for r, row in enumerate(grid) if all(v == row[0] for v in row) and row[0] != bg]
    if not bar_rows:
        return out
    markers = []
    for r, row in enumerate(grid):
        for c in range(w - 1):
            v = row[c]
            if v != bg and row[c + 1] == v and (r not in bar_rows):
                markers.append((r, c))
    if not markers:
        return out
    mr, mc = markers[0]
    br = min(bar_rows, key=lambda r: abs(r - mr))
    nr = mr + (1 if br > mr else -1)
    if 0 <= nr < h:
        out[nr] = [8] * w
    return out
